const VARIABLES_MOCK = [
	'Texto qualquer'
]

function run(inputContent) {
	let redirect = "{{resource.redirect@oportunidades}}"

	let previous = "{{state.previous.id}}";
	let previousSubFlow = "{{stateSubFluxo}}";
	try {
		return {
			"origin": redirect,
			"lastState": previousSubFlow ? previousSubFlow : previous,
			"lastName": "{{state.previous.name}}",
			"inputType": "menu dinamico",
			inputContent
		};

	} catch (error) {
		return "ERROR_FORMATTING_INPUT_CONTENT"
	}
}

function run(input) {
	return input ? JSON.stringify(input).substring(1, input.length + 1) : ""
}

function run(currentCart) {
    try {
        currentCart = typeof currentCart === "string" ? JSON.parse(currentCart) : currentCart;
        const cart = currentCart.cart || [];

        const pedidos = cart.map(item => {
            const p = item.product || {};
            const imagens = (p.images || []).slice().sort((a, b) => a.order - b.order);

            return {
                produto: p.name,
                descricao: (p.description || "").replace(/<[^>]*>/g, "").trim(),
                categoria: p.category,
                marca: (p.brand || "").split(";").join(", "),
                sku: p.sku,
                quantidade: item.quantity,
                valorUnitario: p.currentValue,
                valorOriginal: p.originalValue,
                unidade: p.unitType,
                imagem: imagens.length ? imagens[0].imageUrl : null,
                subtotal: item.subtotal,
                total: item.total
            };
        });

        const descontos = (currentCart.discounts || []).map(d => ({
            tipo: d.type,
            valor: d.value,
            codigo: d.code
        }));

        return JSON.stringify({
            status: currentCart.status,
            pedidos: pedidos,
            descontos: descontos,
            subtotal: Math.round(currentCart.subtotal * 100) / 100,
            total: Math.round(currentCart.total * 100) / 100,
            atualizadoEm: currentCart.updatedAt
        });

    } catch (error) {
        return JSON.stringify({
            error: true,
            message: error.message
        });
    }
}

function run(input) {
    try {
        const data = typeof input === "string" ? JSON.parse(input) : input;
        const pedidos = data.pedidos || [];
        const descontos = data.descontos || [];

        const arred = v => Math.round(v * 100) / 100;

        let valorTotal = 0;
        let valorItens = 0;

        pedidos.forEach(pedido => {
            const quantidade = Number(pedido.quantidade) || 0;
            const valorOriginal = Number(pedido.valorOriginal) || 0;
            const valorUnitario = Number(pedido.valorUnitario) || valorOriginal;

            valorTotal += valorOriginal * quantidade;
            valorItens += valorUnitario * quantidade;
        });

        // Desconto por item (quando valorUnitario < valorOriginal)
        const descontoItens = valorTotal - valorItens;

        // Desconto do carrinho (campo "descontos")
        let valorCalculado = valorItens;
        descontos.forEach(d => {
            const valor = Number(d.valor) || 0;
            if (d.tipo === "percentage") {
                valorCalculado -= valorCalculado * (valor / 100);
            } else {
                valorCalculado -= valor; // desconto em valor fixo
            }
        });
        valorCalculado = Math.max(valorCalculado, 0);

        // O total da API é a fonte oficial; o cálculo é só plano B
        const totalApi = Number(data.total);
        const valorComDesconto = !isNaN(totalApi) && data.total !== null && data.total !== undefined
            ? totalApi
            : valorCalculado;

        return JSON.stringify({
            valorTotal: arred(valorTotal),
            valorComDesconto: arred(valorComDesconto),
            valorDesconto: arred(valorTotal - valorComDesconto),
            descontoItens: arred(descontoItens),
            percentualDesconto: descontos
                .filter(d => d.tipo === "percentage")
                .reduce((acc, d) => acc + (Number(d.valor) || 0), 0),
            temDesconto: valorTotal - valorComDesconto > 0.009
        });

    } catch (error) {
        return JSON.stringify({
            error: true,
            message: error.message
        });
    }
}

function run(pedidosJson) {
    try {
        const dados = typeof pedidosJson === "string" ? JSON.parse(pedidosJson) : pedidosJson;
        const pedidos = (dados && dados.pedidos) || [];

        const normalizar = txt => (txt || "").toString().toLowerCase()
            .normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim();

        // Categoria oficial: "Bovinos" (aceita também "bovina", "carne bovina" etc.)
        const ehBovino = categoria => /\bbovin[oa]s?\b/.test(normalizar(categoria));

        const categorias = [...new Set(
            pedidos
                .map(item => item.categoria)
                .filter(Boolean)
        )];

        const temCategoriasDiferentes = categorias.length > 1;
        const temBovina = categorias.some(ehBovino);
        const temNaoBovina = categorias.some(categoria => !ehBovino(categoria));

        const carrinhoMultiplo = temBovina && temNaoBovina;
        const tipoCarrinho = carrinhoMultiplo ? "multiplo" : "unico";

        return JSON.stringify({
            temCategoriasDiferentes: temCategoriasDiferentes,
            temBovina: temBovina,
            temNaoBovina: temNaoBovina,
            carrinhoMultiplo: carrinhoMultiplo,
            tipoCarrinho: tipoCarrinho,
            categorias: categorias
        });

    } catch (error) {
        return JSON.stringify({
            error: true,
            message: error.message
        });
    }
}

function run(itensJson, retornoValorMinimo) {
    try {
        const dados = typeof itensJson === "string" ? JSON.parse(itensJson) : itensJson;
        const minimoApi = typeof retornoValorMinimo === "string" ? JSON.parse(retornoValorMinimo) : retornoValorMinimo;
        const pedidos = (dados && dados.pedidos) || [];

        function ehBovino(categoria) {
            const c = (categoria || "").toString().toLowerCase()
                .normalize("NFD").replace(/[\u0300-\u036f]/g, "");
            return /\bbovin[oa]s?\b/.test(c);
        }

        // Ordem igual ao Figma. minimo: null = usa o minimum_order_amount da API.
        // Se a MBRF passar a ter mínimo por carrinho/setor, preencha o número aqui.
        const CARRINHOS = [
            { chave: "pedido1", nome: "MBRF", origem: "BRF", minimo: null, filtro: p => !ehBovino(p.categoria) },
            { chave: "pedido2", nome: "Bovinos", origem: "MARFRIG", minimo: null, filtro: p => ehBovino(p.categoria) }
        ];

        const arred = v => Math.round(v * 100) / 100;
        const formatarBRL = v => "R$ " + arred(v).toFixed(2).replace(".", ",").replace(/\B(?=(\d{3})+(?!\d))/g, ".");

        const minimoGeral = Number(minimoApi && minimoApi.minimum_order_amount);
        if (!minimoApi || minimoApi.minimum_order_amount === null || isNaN(minimoGeral)) {
            return JSON.stringify({ error: true, message: "Valor mínimo do pedido indisponível" });
        }

        // Desconto do carrinho (ex.: 50%) aplicado proporcionalmente em cada pedido
        const fator = dados.subtotal ? dados.total / dados.subtotal : 1;

        const saida = { error: false, tipoCarrinho: "multiplo" };
        const blocosResumo = [];

        CARRINHOS.forEach((c, index) => {
            const itens = pedidos.filter(c.filtro);
            const subtotal = itens.reduce((soma, i) =>
                soma + (Number(i.subtotal) || (Number(i.valorUnitario) || 0) * (Number(i.quantidade) || 0)), 0);
            const valor = arred(subtotal * fator);
            const minimo = c.minimo !== null ? c.minimo : minimoGeral;
            const atingiu = valor >= minimo;
            const faltante = atingiu ? 0 : arred(minimo - valor);
            const qtdItens = itens.reduce((soma, i) => soma + (Number(i.quantidade) || 0), 0);
            const k = c.chave;

            saida[k + "Nome"] = c.nome;
            saida[k + "Origem"] = c.origem;
            saida[k + "Valor"] = valor;
            saida[k + "ValorFormatado"] = formatarBRL(valor);
            saida[k + "QtdItens"] = qtdItens;
            saida[k + "QtdProdutos"] = itens.length;
            saida[k + "Minimo"] = arred(minimo);
            saida[k + "MinimoFormatado"] = formatarBRL(minimo);
            saida[k + "AtingiuMinimo"] = atingiu;
            saida[k + "ValorFaltante"] = faltante;
            saida[k + "ValorFaltanteFormatado"] = formatarBRL(faltante);
            saida[k + "Produtos"] = itens.map(i => "• " + i.quantidade + "x " + i.produto).join("\n");

            blocosResumo.push(
                "*Pedido " + (index + 1) + " - " + c.nome + ":*<br>" +
                "Valor: " + formatarBRL(valor) + "<br>" +
                "Qtde. itens: " + qtdItens
            );
        });

        saida.ambosAtingiram = saida.pedido1AtingiuMinimo && saida.pedido2AtingiuMinimo;
        saida.nenhumAtingiu = !saida.pedido1AtingiuMinimo && !saida.pedido2AtingiuMinimo;
        saida.resumoPedidos = blocosResumo.join("<br><br>");

        return JSON.stringify(saida);

    } catch (error) {
        return JSON.stringify({ error: true, message: error.message });
    }
}

function run(retornoTotais, retornoValorMinimo) {
    try {
        const totais = typeof retornoTotais === "string"
            ? JSON.parse(retornoTotais)
            : retornoTotais;

        const valorMinimo = typeof retornoValorMinimo === "string"
            ? JSON.parse(retornoValorMinimo)
            : retornoValorMinimo;

        if (!totais || totais.error) {
            return JSON.stringify({ error: true, message: "Totais do carrinho indisponíveis" });
        }

        const minimo = Number(valorMinimo && valorMinimo.minimum_order_amount);
        if (!valorMinimo || isNaN(minimo) || valorMinimo.minimum_order_amount === null) {
            return JSON.stringify({ error: true, message: "Valor mínimo do pedido indisponível" });
        }

        const arred = v => Math.round(v * 100) / 100;
        const formatarBRL = v => "R$ " + arred(v).toFixed(2).replace(".", ",").replace(/\B(?=(\d{3})+(?!\d))/g, ".");

        // Troque para totais.valorTotal se o mínimo valer sobre o valor sem desconto
        const valorBase = Number(totais.valorComDesconto) || 0;

        const atingiuMinimo = valorBase >= minimo;
        const valorFaltante = atingiuMinimo ? 0 : arred(minimo - valorBase);

        return JSON.stringify({
            atingiuMinimo: atingiuMinimo,
            valorBase: arred(valorBase),
            valorMinimo: arred(minimo),
            valorFaltante: valorFaltante,
            valorBaseFormatado: formatarBRL(valorBase),
            valorMinimoFormatado: formatarBRL(minimo),
            valorFaltanteFormatado: formatarBRL(valorFaltante)
        });

    } catch (error) {
        return JSON.stringify({
            error: true,
            message: error.message
        });
    }
}

function run(input) {
  try {
    let opcoesMenu = {
      "1": "Completar pedido",
      "2": "Encerrar",
    };

    let menuRegex = {
      // Adicionado: 1, um, completar (pedido), finalizar, fechar
      "1": /\b(?:1|um|sim|claro|confirmo|positivo|ok|okay|pode\s+ser|aceito|continuar|completar(?:\s+pedido)?)\b/i,

      // Adicionado: 2, dois, encerrar, cancelar, sair, parar
      "2": /\b(?:2|dois|n[aã]o|negativo|desistir|prefiro\s+n[aã]o|encerrar|cancelar|sair|parar)\b/i,
    };

    input = input.trim();

    for (let prop in menuRegex) {
      if (menuRegex[prop].test(input)) {
        return opcoesMenu[prop];
      }
    }

    return "Input inesperado";
  } catch (error) {
    return "Input inesperado";
  }
}

