function run(resposta) {
    try {
        // Regra do cliente: é boleto quando o código da condição NÃO é "PIX" E NÃO começa com "BP"
        let ehBoleto = function (codigo) {
            codigo = String(codigo || "").trim().toUpperCase();
            if (!codigo) return false;
            if (codigo === "PIX") return false;
            if (codigo.indexOf("BP") === 0) return false;
            return true;
        };

        let LIMITE_LINHAS = 10;
        let LIMITE_TITULO = 20;     // limite de título da lista do WhatsApp
        let LIMITE_DESCRICAO = 72;

        let dados = typeof resposta === "string" ? JSON.parse(resposta) : resposta;

        let cortar = function (txt, limite) {
            txt = (txt || "").toString().trim();
            return txt.length > limite ? txt.substring(0, limite - 3).trim() + "..." : txt;
        };

        // Procura em qualquer nível do retorno os objetos que tenham "default_payment_condition"
        let condicoes = [];
        let coletar = function (obj) {
            if (Array.isArray(obj)) {
                obj.forEach(coletar);
            } else if (obj && typeof obj === "object") {
                if (Object.prototype.hasOwnProperty.call(obj, "default_payment_condition")) condicoes.push(obj);
                for (let k in obj) {
                    if (obj[k] && typeof obj[k] === "object") coletar(obj[k]);
                }
            }
        };
        coletar(dados);

        let codigosVistos = {};
        let rows = condicoes
            .filter(function (item) {
                return ehBoleto(item.code);
            })
            .filter(function (item) {
                let chave = String(item.code || item.name || "").trim().toUpperCase();
                if (codigosVistos[chave]) return false;
                codigosVistos[chave] = true;
                return true;
            })
            .slice(0, LIMITE_LINHAS)
            .map(function (item, i) {
                let nome = (item.name || "Boleto").toString().trim();
                return {
                    // Título único: o menu dinâmico identifica a opção escolhida pelo título
                    title: cortar((i + 1) + ". " + nome, LIMITE_TITULO),
                    description: cortar("Boleto - " + nome, LIMITE_DESCRICAO),
                    name: item.name || "",
                    code: item.code || "",
                    deadline_time: item.deadline_time,
                    dados: true
                };
            });

        if (!rows.length) {
            return JSON.stringify({ temBoleto: false, total: 0 });
        }

        return JSON.stringify({
            temBoleto: true,
            total: rows.length,
            body: "Agora escolha a <b>condição de pagamento</b> do seu pedido. 💳",
            footer: "Selecione uma opção abaixo:",
            button: "Ver opções",
            categories: [
                {
                    title: "Boleto",
                    rows: rows
                }
            ]
        });
    } catch (e) {
        return JSON.stringify({ temBoleto: false, total: 0, error: true, message: e.message });
    }
}

