function run(retornoCheckoutGet, dataEntregaISO, dataEntregaChave) {
    try {
    // O Blip converte strings ISO em DateTime ao ler JSON com "@" e devolve "MM/dd/yyyy HH:mm:ss".
    // Por isso a data trafega como chave numerica (yyyyMMdd) e e normalizada aqui.
    let dataISO = function (chave, alternativa) {
        let dois = function (n) { n = String(n); return n.length < 2 ? "0" + n : n; };
        let c = String(chave || "").replace(/\D/g, "");
        if (c.length === 8) return c.substring(0, 4) + "-" + c.substring(4, 6) + "-" + c.substring(6, 8);
        let s = String(alternativa || "").trim();
        let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
        if (m) return m[1] + "-" + m[2] + "-" + m[3];
        m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/); // formato do Blip: MM/dd/yyyy
        if (m) return m[3] + "-" + dois(m[1]) + "-" + dois(m[2]);
        return "";
    };

        let MESES = ["janeiro", "fevereiro", "marco", "abril", "maio", "junho", "julho", "agosto", "setembro", "outubro", "novembro", "dezembro"];
        let semAcento = function (s) {
            return String(s || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
        };

        // Converte o nome do método ("Sexta-feira, 02 de Outubro de 2026") em "2026-10-02"
        let dataDoNome = function (nome) {
            let t = semAcento(nome);
            let m = t.match(/(\d{1,2})\s+de\s+([a-z]+)\s+de\s+(\d{4})/);
            if (m) {
                let mes = MESES.indexOf(m[2]) + 1;
                if (mes > 0) return m[3] + "-" + (mes < 10 ? "0" : "") + mes + "-" + (m[1].length < 2 ? "0" : "") + m[1];
            }
            let b = t.match(/(\d{2})\/(\d{2})\/(\d{4})/);
            if (b) return b[3] + "-" + b[2] + "-" + b[1];
            let iso = t.match(/(\d{4}-\d{2}-\d{2})/);
            return iso ? iso[1] : "";
        };

        let data = typeof retornoCheckoutGet === "string" ? JSON.parse(retornoCheckoutGet) : retornoCheckoutGet;
        let grupos = (data && data.deliveryGroups && data.deliveryGroups.items) || [];
        let grupo = grupos[0] || {};
        let metodos = grupo.availableDeliveryMethods || [];
        let selecionado = grupo.selectedDeliveryMethod || null;
        let alvo = dataISO(dataEntregaChave, dataEntregaISO);

        let escolhido = metodos.filter(function (m) { return dataDoNome(m.name) === alvo; })[0] || null;
        let temGrupo = !!grupo.id;
        let temMetodos = metodos.length > 0;
        let temSelecionado = !!(selecionado && selecionado.id);

        return JSON.stringify({
            // ok: ha grupo e pelo menos um metodo disponivel para selecionar
            ok: temGrupo && temMetodos,
            // temGrupo mesmo sem metodos (ex.: aguardando precificacao/endereco)
            temGrupo: temGrupo,
            semMetodos: temGrupo && !temMetodos,
            deliveryGroupId: grupo.id || "",
            totalMetodos: metodos.length,
            temSelecionado: temSelecionado,
            primeiroMetodoId: metodos[0] ? metodos[0].id : "",
            // usa o metodo da data desejada; se nao achar, cai no primeiro disponivel
            metodoEscolhidoId: escolhido ? escolhido.id : (metodos[0] ? metodos[0].id : ""),
            dataDisponivel: !!escolhido,
            // Tolerante: se ja ha um metodo selecionado no checkout, considera correto
            // (o metodo correto foi aplicado na fase de selecao). Nao depende do parse do name.
            selecionadoCorreto: temSelecionado,
            selecionadoNome: selecionado ? (selecionado.name || "") : ""
        });
    } catch (e) {
        return JSON.stringify({ ok: false, error: true, semMetodos: false, temGrupo: false, message: e.message });
    }
}

