function run(itensCarrinhoFormatado, retornoProdutos) {
    try {
        let smart = typeof itensCarrinhoFormatado === "string" ? JSON.parse(itensCarrinhoFormatado) : itensCarrinhoFormatado;
        let prods = typeof retornoProdutos === "string" ? JSON.parse(retornoProdutos) : retornoProdutos;

        // SKU -> Id do Product2 na loja
        let idPorSku = {};
        ((prods && prods.products) || []).forEach(function (p) {
            if (!p || p.success === false || !p.id) return;
            let sku = p.sku || (p.fields && (p.fields.StockKeepingUnit || p.fields.ProductCode)) || "";
            if (sku) idPorSku[String(sku).trim()] = p.id;
        });

        // Soma quantidades de SKUs repetidos
        let qtdPorSku = {}, nomePorSku = {}, ordem = [];
        ((smart && smart.pedidos) || []).forEach(function (p) {
            let sku = String(p.sku || "").trim();
            let qtd = Number(p.quantidade) || 0;
            if (!sku || qtd <= 0) return;
            if (!(sku in qtdPorSku)) { qtdPorSku[sku] = 0; ordem.push(sku); }
            qtdPorSku[sku] += qtd;
            nomePorSku[sku] = p.produto || sku;
        });

        let batchInput = [], naoEncontrados = [];
        ordem.forEach(function (sku) {
            if (!idPorSku[sku]) { naoEncontrados.push(nomePorSku[sku]); return; }
            batchInput.push({ richInput: { productId: idPorSku[sku], quantity: String(qtdPorSku[sku]), type: "Product" } });
        });

        return JSON.stringify({
            ok: batchInput.length > 0 && naoEncontrados.length === 0,
            totalItens: batchInput.length,
            totalNaoEncontrados: naoEncontrados.length,
            naoEncontrados: naoEncontrados.join(", "),
            body: JSON.stringify({ inputs: batchInput })
        });
    } catch (e) {
        return JSON.stringify({ ok: false, totalItens: 0, totalNaoEncontrados: 0, naoEncontrados: "", body: "{}", error: e.message });
    }
}

