function run(retornoItensCarrinhoSF, itensCarrinhoFormatado, retornoProdutos, retornoRecalculoSync) {
    try {
        let parse = function (v) {
            if (!v) return {};
            if (typeof v !== "string") return v;
            try { return JSON.parse(v); } catch (e) { return {}; }
        };
        let num = function (v) {
            if (v === null || v === undefined || v === "" || typeof v === "object") return null;
            let n = Number(v);
            return isNaN(n) ? null : n;
        };
        let arred = function (v) { return Math.round(v * 100) / 100; };
        let id15 = function (v) { return String(v || "").substring(0, 15); };
        let CAMPOS_TOTAL = ["totalAmount", "totalPrice", "totalLineAmount"];
        let CAMPOS_UNIT = ["unitAdjustedPrice", "unitAdjustedAmount", "salesPrice", "unitPrice"];

        // Preço de um cart-item: primeiro total positivo; senão unitário x quantidade
        let precoDe = function (o, qtd) {
            let k, v;
            let total = 0, lista = 0;
            for (k = 0; k < CAMPOS_TOTAL.length && !total; k++) { v = num(o[CAMPOS_TOTAL[k]]); if (v > 0) total = v; }
            for (k = 0; k < CAMPOS_UNIT.length && !total; k++) { v = num(o[CAMPOS_UNIT[k]]); if (v > 0) total = v * qtd; }
            v = num(o.totalListPrice); if (v > 0) lista = v;
            if (!lista) { v = num(o.listPrice); if (v > 0) lista = v * qtd; }
            if (!total) total = lista;
            return { total: total, lista: lista || total };
        };

        let sf = parse(retornoItensCarrinhoSF);
        let smart = parse(itensCarrinhoFormatado);
        let prods = parse(retornoProdutos);
        let recalc = parse(retornoRecalculoSync);
        let dadosRecalc = recalc.data || recalc;

        let smartPorSku = {};
        let listaSmart = smart.pedidos || [];
        for (let a = 0; a < listaSmart.length; a++) {
            if (listaSmart[a] && listaSmart[a].sku) smartPorSku[String(listaSmart[a].sku)] = listaSmart[a];
        }
        let skuPorId = {};
        let listaProd = prods.products || [];
        for (let b = 0; b < listaProd.length; b++) {
            if (listaProd[b] && listaProd[b].id && listaProd[b].sku) skuPorId[id15(listaProd[b].id)] = String(listaProd[b].sku);
        }

        // Avisos de preço do recálculo da Central ("Produto com preço zerado:01t...")
        let avisos = [], idsSemPrecoCentral = {};
        let msgs = (dadosRecalc.messagesSummary && dadosRecalc.messagesSummary.limitedMessages) || [];
        for (let c = 0; c < msgs.length; c++) {
            let texto = String((msgs[c] && msgs[c].message) || "");
            if ((msgs[c] && msgs[c].type === "Pricing") || texto.toLowerCase().indexOf("zerado") >= 0) {
                avisos.push(texto);
                let pos = texto.indexOf("01t");
                if (pos >= 0) idsSemPrecoCentral[texto.substring(pos, pos + 15)] = true;
            }
        }

        let pedidos = [], semPreco = [], semPrecoCentral = [], precosPrimeiroItem = null;
        let itens = sf.cartItems || [];
        for (let i = 0; i < itens.length; i++) {
            let it = (itens[i] && itens[i].cartItem) || itens[i] || {};
            if (it.type && it.type !== "Product") continue;
            let det = it.productDetails || {};
            let pid = it.productId || det.productId || "";
            let sku = String(det.sku || it.sku || skuPorId[id15(pid)] || "");
            let ref = smartPorSku[sku] || {};
            let qtd = num(it.quantity) || 0;
            let p = precoDe(it, qtd);
            let nome = det.name || it.name || ref.produto || sku;

            if (!precosPrimeiroItem) precosPrimeiroItem = {
                totalAmount: it.totalAmount, totalPrice: it.totalPrice, salesPrice: it.salesPrice,
                listPrice: it.listPrice, unitAdjustedPrice: it.unitAdjustedPrice
            };
            if (!(p.total > 0)) {
                semPreco.push(nome);
                if (idsSemPrecoCentral[id15(pid)]) semPrecoCentral.push(nome);
            }

            pedidos.push({
                produto: nome,
                descricao: ref.descricao || "",
                categoria: ref.categoria || "",
                marca: ref.marca || "",
                sku: sku,
                productId: pid,
                quantidade: qtd,
                valorUnitario: qtd ? arred(p.total / qtd) : 0,
                valorOriginal: qtd ? arred(p.lista / qtd) : 0,
                unidade: ref.unidade || "",
                imagem: ref.imagem || null,
                subtotal: arred(p.total),
                total: arred(p.total)
            });
        }

        let soma = 0, somaLista = 0;
        for (let j = 0; j < pedidos.length; j++) {
            soma += pedidos[j].total;
            somaLista += pedidos[j].valorOriginal * pedidos[j].quantidade;
        }
        soma = arred(soma); somaLista = arred(somaLista);

        return JSON.stringify({
            ok: pedidos.length > 0 && semPreco.length === 0,
            origem: "salesforce",
            status: smart.status || "",
            pedidos: pedidos,
            descontos: [],
            subtotal: soma,
            total: soma,
            totalLista: somaLista,
            totalSmartSales: num(smart.total),
            semPreco: semPreco.join(", "),
            precoZeradoCentral: semPrecoCentral.length > 0,
            semPrecoCentral: semPrecoCentral.join(", "),
            motivo: !pedidos.length ? "Carrinho Salesforce sem itens" : (semPreco.length ? "Carrinho Salesforce sem preço calculado" : ""),
            diagnostico: {
                statusCarrinho: (sf.cartSummary && sf.cartSummary.status) || "",
                avisosRecalculo: avisos,
                precosPrimeiroItem: precosPrimeiroItem
            }
        });
    } catch (e) {
        return JSON.stringify({ ok: false, error: true, motivo: "Erro no script: " + e.message, pedidos: [], descontos: [], subtotal: 0, total: 0 });
    }
}

