function run(statusConta, retornoConta, statusCredito, retornoCredito) {
  // Status de crédito do Ygg considerados elegíveis.
  // "RELEASED" é o que vem no payload de exemplo; confirmar a lista completa com o time do Ygg.
  let STATUS_CREDITO_OK = ["RELEASED"];
  let STATUS_CREDITO_BLOQUEADO = ["BLOCKED", "BLOQUEADO"]; // confirmar nomes reais

  let resultado = {
    elegivel: "erro",
    motivo: "ERRO_API",
    contaAtiva: null,
    creditoStatus: null,
    creditoBloqueado: null,
    creditoDisponivel: null,
    pedidoMinimo: null,
    mensagem: ""
  };

  function parse(v) {
    if (v === null || v === undefined || v === "") return null;
    if (typeof v === "object") return v;
    try { return JSON.parse(v); } catch (e) { return null; }
  }
  function isTrue(v) { return v === true || String(v).toLowerCase() === "true"; }
  function toNumber(v) {
    if (v === null || v === undefined || v === "") return null;
    let n = Number(v);
    return isNaN(n) ? null : n;
  }
  function fim(elegivel, motivo, mensagem) {
    resultado.elegivel = elegivel;
    resultado.motivo = motivo;
    resultado.mensagem = mensagem || "";
    return JSON.stringify(resultado); // string evita problemas ao salvar em variável no Blip
  }

  try {
    // 1) Conta - GET /ecommerce/account/{accountId}
    if (String(statusConta) !== "200") return fim("erro", "ERRO_API_CONTA");
    let conta = parse(retornoConta);
    if (!conta) return fim("erro", "ERRO_API_CONTA");
    resultado.contaAtiva = isTrue(conta.active);

    // 2) Crédito - POST /ecommerce/credit
    if (String(statusCredito) !== "200") return fim("erro", "ERRO_API_CREDITO");
    let credito = parse(retornoCredito);
    if (!credito) return fim("erro", "ERRO_API_CREDITO");

    resultado.creditoStatus = credito.status ? String(credito.status).toUpperCase() : null;
    resultado.creditoBloqueado = isTrue(credito.blocked) ||
      STATUS_CREDITO_BLOQUEADO.indexOf(resultado.creditoStatus) !== -1;
    resultado.creditoDisponivel = toNumber(credito.available);
    resultado.pedidoMinimo = toNumber(credito.minimalOrderValue);

    // 3) Regras de elegibilidade
    if (!resultado.contaAtiva) {
      return fim("false", "CONTA_INATIVA",
        "Identificamos que sua <b>conta está inativa</b> no momento, por isso não é possível seguir com o pedido por aqui.");
    }
    if (resultado.creditoBloqueado) {
      return fim("false", "CREDITO_BLOQUEADO",
        "Identificamos que o <b>crédito da sua conta está bloqueado</b>, por isso não é possível seguir com o pedido por aqui.");
    }
    if (STATUS_CREDITO_OK.indexOf(resultado.creditoStatus) === -1) {
      return fim("false", "CREDITO_INATIVO",
        "Identificamos que sua conta <b>não possui crédito ativo</b> no momento, por isso não é possível seguir com o pedido por aqui.");
    }
    if (credito.overdue !== null && credito.overdue !== undefined && toNumber(credito.overdue) !== 0) {
      return fim("false", "CREDITO_EM_ATRASO",
        "Identificamos <b>pendências financeiras</b> na sua conta, por isso não é possível seguir com o pedido por aqui.");
    }
    let minimo = resultado.pedidoMinimo || 0;
    if (resultado.creditoDisponivel === null || resultado.creditoDisponivel < minimo || resultado.creditoDisponivel <= 0) {
      return fim("false", "CREDITO_INSUFICIENTE",
        "Identificamos que o <b>crédito disponível</b> não é suficiente para o pedido mínimo, por isso não é possível seguir com o pedido por aqui.");
    }
    return fim("true", "ELEGIVEL");
  } catch (e) {
    return fim("erro", "ERRO_SCRIPT");
  }
}

