function run(statusUsuario, retornoUsuario, statusGerenciadas, retornoGerenciadas) {
  function parse(v) { if (!v) return null; if (typeof v === "object") return v; try { return JSON.parse(v); } catch (e) { return null; } }
  try {
    let ids = [];
    function add(id) { if (id && ids.indexOf(String(id)) === -1) ids.push(String(id)); }

    // 1) Conta principal (User.AccountId)
    if (String(statusUsuario) === "200") {
      let u = parse(retornoUsuario);
      if (u && u.records && u.records.length) add(u.records[0].AccountId);
    }
    // 2) Contas gerenciadas
    if (String(statusGerenciadas) === "200") {
      let g = parse(retornoGerenciadas);
      let lista = (g && (g.externalManagedAccounts || g.managedAccounts)) || [];
      for (let i = 0; i < lista.length; i++) add(lista[i].accountId || lista[i].id);
    }
    if (!ids.length) return "";

    let inClause = ids.map(function (id) { return "'" + id.replace(/'/g, "") + "'"; }).join(",");
    return encodeURIComponent("SELECT Id, Name, CNPJ__c, ParentId FROM Account WHERE Id IN (" + inClause + ")");
  } catch (e) { return ""; }
}

function run(retornoContasSF) {
  try {
    let dados = typeof retornoContasSF === "string" ? JSON.parse(retornoContasSF) : retornoContasSF;
    let regs = (dados && dados.records) || [];
    let campos = "items { active shared_id description " +
      "addresses { city complements federative_unit country neighborhood street_number street type zip_code } " +
      "sales_informations { partners { partner_function addresses { complements city country federative_unit street neighborhood type street_number zip_code } } } }";
    let partes = [], vistos = {};
    regs.forEach(function (r) {
      let doc = String(r.CNPJ__c || "").replace(/\D/g, "");
      if (!doc || vistos[doc]) return;
      vistos[doc] = true;
      // alias por CNPJ: uma única requisição GraphQL busca todos os clientes
      partes.push("c" + doc + ": get_person_customer(filters: { documents: { document_value: \"" + doc + "\" } }) { " + campos + " }");
    });
    if (!partes.length) return "";
    return JSON.stringify({ query: "query BuscaContas { " + partes.join(" ") + " }" });
  } catch (e) { return ""; }
}

function run(statusUsuario, retornoUsuario, statusContasSF, retornoContasSF, statusClientesYgg, retornoClientesYgg) {
  function parse(v) { if (!v) return null; if (typeof v === "object") return v; try { return JSON.parse(v); } catch (e) { return null; } }
  function limpa(v) { return String(v == null ? "" : v).replace(/["\\]/g, "'").replace(/\s+/g, " ").trim(); }

  function montaEndereco(a) {
    if (!a) return null;
    let rua = limpa(a.street), num = limpa(a.street_number), comp = limpa(a.complements),
        bairro = limpa(a.neighborhood), cidade = limpa(a.city), uf = limpa(a.federative_unit), cep = limpa(a.zip_code);
    let linha1 = rua + (num ? ", " + num : "") + (comp ? " - " + comp : "");
    let local = cidade + (uf ? "/" + uf : "");
    let completo = [linha1, bairro, local].filter(Boolean).join(" - ") + (cep ? " - CEP " + cep : "");
    let curto = [rua + (num ? ", " + num : ""), local].filter(Boolean).join(" - ");
    return completo ? { completo: completo, curto: curto, rua: linha1, cidade: cidade, uf: uf, cep: cep.replace(/\D/g, "") } : null;
  }

  function enderecoCliente(cli) {
    if (!cli) return null;
    let end = montaEndereco((cli.addresses || [])[0]);
    if (end) return end;
    // fallback: endereço do parceiro de entrega (shipping_code)
    let sales = cli.sales_informations || [];
    for (let i = 0; i < sales.length; i++) {
      let parts = sales[i].partners || [];
      for (let j = 0; j < parts.length; j++) {
        if (parts[j].partner_function === "shipping_code" && parts[j].addresses && parts[j].addresses.length) {
          end = montaEndereco(parts[j].addresses[0]);
          if (end) return end;
        }
      }
    }
    return null;
  }

  try {
    if (String(statusContasSF) !== "200") return { ok: false, total: 0, erro: "ERRO_CONTAS_SF" };
    let sf = parse(retornoContasSF);
    let regs = (sf && sf.records) || [];
    if (!regs.length) return { ok: false, total: 0, erro: "SEM_CONTAS" };

    let principalId = "";
    let u = parse(retornoUsuario);
    if (String(statusUsuario) === "200" && u && u.records && u.records.length) principalId = u.records[0].AccountId || "";

    // Índice dos clientes Ygg por CNPJ (alias "c<cnpj>")
    let porCnpj = {};
    let ygg = String(statusClientesYgg) === "200" ? parse(retornoClientesYgg) : null;
    let data = (ygg && ygg.data) || {};
    Object.keys(data).forEach(function (alias) {
      let itens = (data[alias] && data[alias].items) || [];
      if (itens.length) porCnpj[alias.replace(/^c/, "")] = itens[0];
    });

    let contas = regs.map(function (r) {
      let cnpj = String(r.CNPJ__c || "").replace(/\D/g, "");
      let cli = porCnpj[cnpj];
      let end = enderecoCliente(cli);
      return {
        accountId: r.Id,
        nome: limpa(r.Name || (cli && cli.description) || "Conta sem nome"),
        cnpj: cnpj,
        codigoCliente: cli ? limpa(cli.shared_id) : "",
        endereco: end ? end.completo : "Endereço não disponível",
        enderecoCurto: end ? end.curto : "Endereço não disponível",
        enderecoRua: end ? end.rua : "",
        enderecoCidade: end ? end.cidade : "",
        enderecoUf: end ? end.uf : "",
        enderecoCep: end ? end.cep : "",
        temEndereco: !!end,
        principal: r.Id === principalId
      };
    });

    // conta principal primeiro, depois ordem alfabética
    contas.sort(function (a, b) {
      if (a.principal !== b.principal) return a.principal ? -1 : 1;
      return a.nome.localeCompare(b.nome);
    });

    let principal = contas.filter(function (c) { return c.principal; })[0] || null;
    return {
      ok: true,
      total: contas.length,
      contas: contas,
      enderecoPrincipal: principal ? principal.endereco : "",
      yggOk: String(statusClientesYgg) === "200"
    };
  } catch (e) {
    return { ok: false, total: 0, erro: "ERRO_SCRIPT", mensagem: e.message };
  }
}

