function run(contasVinculadas) {
  function fmtCnpj(d) {
    d = String(d || "").replace(/\D/g, "");
    if (d.length !== 14) return d || "CNPJ não informado";
    return d.replace(/^(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})$/, "$1.$2.$3/$4-$5");
  }

  try {
    let dados = typeof contasVinculadas === "string" ? JSON.parse(contasVinculadas) : contasVinculadas;
    let contas = (dados && dados.contas) || [];
    if (!contas.length) return JSON.stringify({ temContas: false, total: 0 });

    let rows = contas.map(function (c, i) {
      // número no início garante títulos únicos mesmo com o corte de 20 caracteres do WhatsApp
      let row = {
        title: (i + 1) + ". " + c.nome,
        description: "CNPJ: " + fmtCnpj(c.cnpj),
        accountId: c.accountId,
        nome: c.nome,
        cnpj: c.cnpj,
        codigoCliente: c.codigoCliente,
        endereco: c.endereco,
        principal: c.principal,
        dados: true
      };
      return row;
    });

    // Lista no corpo (quick reply/botões não exibem descrição). "\\n" literal: o subfluxo injeta o body dentro de uma string JS.
    let corpo = "Encontrei <b>" + contas.length + " contas</b> vinculadas ao seu e-mail.";
    corpo += "\n\n<b>Com qual conta você quer seguir?</b>";

    return JSON.stringify({
      temContas: true,
      total: rows.length,
      body: corpo,
      footer: "Selecione uma das contas.",
      button: "Ver contas",
      categories: [{ title: "Contas vinculadas", rows: rows }]
    });
  } catch (e) {
    return JSON.stringify({ temContas: false, total: 0, error: true, message: e.message });
  }
}

