function run(nome, rua, cidade, uf, cep, dataChave, dataDesejada) {
    try {
        let limpa = function (s) { return String(s || "").trim(); };
    // O Blip converte strings ISO em DateTime ao ler JSON com "@" e devolve "MM/dd/yyyy HH:mm:ss".
    // Por isso a data trafega como chave numerica (yyyyMMdd) e e normalizada aqui.
    let dataISO = function (chave, alternativa) {
        let dois = function (n) { n = String(n); return n.length < 2 ? "0" + n : n; };
        let c = String(chave || "").replace(/\D/g, "");
        if (c.length === 8) return c.substring(0, 4) + "-" + c.substring(4, 6) + "-" + c.substring(6, 8);
        let s = String(alternativa || "").trim();
        let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
        if (m) return m[1] + "-" + m[2] + "-" + m[3];
        m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/); // formato do Blip: MM/dd/yyyy
        if (m) return m[3] + "-" + dois(m[1]) + "-" + dois(m[2]);
        return "";
    };
        let corpo = {};
        if (limpa(rua)) {
            let digitos = limpa(cep).replace(/\D/g, "");
            corpo.DeliverToName = limpa(nome) || limpa(rua);
            corpo.DeliverToStreet = limpa(rua);
            corpo.DeliverToCity = limpa(cidade);
            corpo.DeliverToStateCode = limpa(uf).toUpperCase();
            corpo.DeliverToPostalCode = digitos.length === 8 ? digitos.substring(0, 5) + "-" + digitos.substring(5) : limpa(cep);
            corpo.DeliverToCountryCode = "BR";
        }
        let dia = dataISO(dataChave, dataDesejada);
        // meio-dia UTC = 09:00 de Brasilia, garante o mesmo dia nos dois fusos
        if (dia) corpo.DesiredDeliveryDate = dia + "T12:00:00.000Z";
        return JSON.stringify(corpo);
    } catch (e) {
        return "{}";
    }
}
